<script setup lang="ts">import type { MasonryLayoutDetail } from '@fex-design/vue/primitive/masonry';import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/vue/primitive/masonry';import { ref } from 'vue';import { masonryItems } from './data';const columns=ref<Record<string,number>>({});const layout=(value:MasonryLayoutDetail)=>columns.value=Object.fromEntries(value.items.map(item=>[String(item.key),item.column+1]))</script>
<template><MasonryRoot :columns="3" :gap="16" :on-layout-change="layout"><MasonryViewport><MasonryItem v-for="(item,index) in masonryItems.slice(0,9)" :key="item.id" :item-key="item.id" :index="index"><article class="rounded-md border border-border bg-background p-space-md" :style="{minHeight:`${item.height/2}px`}"><strong>{{ item.title }}</strong><p class="mt-2 text-xs text-muted-foreground">输入序号 {{ index+1 }} · key {{ item.id }} · 最终第 {{ columns[item.id] ?? '…' }} 列</p></article></MasonryItem></MasonryViewport></MasonryRoot></template>
